scripts.script:
while wait() do
for i ,v in pairs(game.Players:GetChildren()) do
local args = {
	{
		DoubleDamage = true,
		HitType = 1,
		Targets = {
			v.Character
		},
		ImpactPosition = vector.create(0,0,0),
		Weapon = 1
	}
}
game:GetService("ReplicatedStorage"):WaitForChild("Library"):WaitForChild("Net"):WaitForChild("_NetManaged"):WaitForChild("ValidateHit"):FireServer(unpack(args))
end
end
